mapper.select:
select * from (SELECT T1.ENTRUST_ID ,T1.ENTRUST_STATUS ,case when T2.TARGET_TYPE = '01' then ROUND(T4.ORDER_FINISH_AMT/T1.ENTRUST_NUM,4) else ROUND(T4.ORDER_FINISH_AMT/T1.ENTRUST_AMT,4) end as implementPercent ,case when T2.TARGET_TYPE = '01' then ROUND(T4.ENT_FINISH_AMT/T1.ENTRUST_NUM,4) else ROUND(T4.ENT_FINISH_AMT/T1.ENTRUST_AMT,4) end as dealPercent ,T5.PORTFOLIO_ID ,T5.PORTFOLIO_NAME ,T1.FINPROD_ID ,T7.FINPROD_MARKET_ID ,CASE WHEN T1.PS IN ('03','04') THEN T1.FINPROD_ID ELSE T7.FINPROD_ABBR END AS FINPROD_ABBR ,T1.FINPROD_TYPE2 ,T1.TRADE_MARKET ,T1.TRADE_PLAT ,T1.PS ,T2.SEC_ACCT_ID ,SSAI.SEC_ACCT_NAME ,T2.DEAL_CUR_ACCT as dealCurAcct ,c1.acctName as dealCurAcctName ,T1.PRICE_MODEL ,T2.DEAL_MODE as declaType ,CASE WHEN T1.PS IN (#{PS_T68}, #{PS_T69}, #{PS_03}, #{PS_04}) THEN T1.PRICE * 100 ELSE T1.PRICE END price /* ,T1.ENTRUST_AMT*NVL(T1.PRICE,1) ENTRUST_AMT*/ ,T1.ENTRUST_AMT ENTRUST_AMT ,T1.ENTRUST_NUM ENTRUST_NUM ,T1.VDATE ,T1.MDATE ,T2.FULL_PRICE as fprice ,T2.MATURE_YIELD * 100 as yield ,T2.CAL_MODE as calMode ,T2.COUNTER_SEAT ,T2.COUNTER_CON_NO ,T1.ENTRUST_TYPE ,fpt.TYPE_8 paAssetType ,case when T1.STOCK_ID IS NOT NULL THEN T1.STOCK_ID ELSE T7.FINPROD_MARKET_ID END finprodMarketId /*,T7.FINPROD_MARKET_ID finprodMarketId*/ ,T1.COUNTER_ID ,T2.TARGET_TYPE ,T2.TRADER ,T2.COUNTER_ORG ,T1.COUNTER_TRADER ,T2.ASSET_TYPE ,T1.CREATE_TIME FROM ETR_ENTRUST T1 INNER JOIN ETR_ENTRUST_ADD T2 ON T2.ENTRUST_ID = T1.ENTRUST_ID and (T2.ASSET_TYPE1 != 'H01' or T2.ASSET_TYPE1 is null) LEFT JOIN ETR_FINISH_STATUS T4 ON T4.ENTRUST_ID = T1.ENTRUST_ID AND T1.ENTRUST_ID = T4.TRADE_ID LEFT JOIN PTL_PORTFOLIO T5 ON T5.PORTFOLIO_ID = T1.PORTFOLIO_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY T6 ON T6.PORTFOLIO_ID = T5.PORTFOLIO_ID
AND T6.USER_ID = #{userId}
LEFT JOIN FIN_PRODUCT T7 ON T7.FINPROD_ID = T1.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE fpt ON fpt.FINPROD_ID = T7.FINPROD_ID LEFT JOIN STL_SEC_ACCT_INFO SSAI ON T2.SEC_ACCT_ID = SSAI.SEC_ACCT_ID
left join (select distinct ACCT_NO acctNo1, BUSI_ACCT_NO busiAcctNo1, CCY ccy, ACCT_NAME acctName from STL_CAPACCT_INFO) c1 on T2.DEAL_CUR_ACCT = c1.acctNo1 and nvl(T1.CCY, 'CNY') = c1.ccy where T1.TRADE_MARKET in ('03','04') AND T2.ASSET_TYPE NOT IN ('F17')
AND T1.ENTRUST_DATE = to_date(#{sysDate},'yyyy-MM-dd')
AND T1.ENTRUST_ID = #{entrustId}
AND T1.ENTRUST_STATUS = #{entrustStatus}
AND T1.ENTRUST_DATE >=to_date(#{startDate},'yyyy-MM-dd')
AND T1.ENTRUST_DATE <=to_date(#{endDate},'yyyy-MM-dd')
union all SELECT T1.ENTRUST_ID ,T1.ENTRUST_STATUS ,case when T2.TARGET_TYPE = '01' then ROUND(T4.ORDER_FINISH_AMT/T1.ENTRUST_NUM,4) else ROUND(T4.ORDER_FINISH_AMT/T1.ENTRUST_AMT,4) end as implementPercent ,case when T2.TARGET_TYPE = '01' then ROUND(T4.ENT_FINISH_AMT/T1.ENTRUST_NUM,4) else ROUND(T4.ENT_FINISH_AMT/T1.ENTRUST_AMT,4) end as dealPercent ,T5.PORTFOLIO_ID ,T5.PORTFOLIO_NAME ,T1.FINPROD_ID ,T7.FINPROD_MARKET_ID ,CASE WHEN T1.PS IN ('03','04') THEN T1.FINPROD_ID ELSE T7.FINPROD_ABBR END AS FINPROD_ABBR ,T1.FINPROD_TYPE2 ,T1.TRADE_MARKET ,T1.TRADE_PLAT ,T1.PS ,T2.SEC_ACCT_ID ,SSAI.SEC_ACCT_NAME ,T2.DEAL_CUR_ACCT ,c1.acctName as dealCurAcctName ,T1.PRICE_MODEL ,T2.DEAL_MODE as declaType ,CASE WHEN T1.PS IN (#{PS_T68}, #{PS_T69}, #{PS_03}, #{PS_04}) THEN T1.PRICE * 100 ELSE T1.PRICE END price /* ,T1.ENTRUST_AMT*NVL(T1.PRICE,1) ENTRUST_AMT*/ ,T1.ENTRUST_AMT ENTRUST_AMT ,T1.ENTRUST_NUM ENTRUST_NUM ,T1.VDATE ,T1.MDATE ,T2.FULL_PRICE as fprice ,T2.MATURE_YIELD * 100 as yield ,T2.CAL_MODE as calMode ,T2.COUNTER_SEAT ,T2.COUNTER_CON_NO ,T1.ENTRUST_TYPE ,fpt.TYPE_8 paAssetType ,case when T1.STOCK_ID IS NOT NULL THEN T1.STOCK_ID ELSE T7.FINPROD_MARKET_ID END finprodMarketId /*,T7.FINPROD_MARKET_ID finprodMarketId*/ ,T1.COUNTER_ID ,T2.TARGET_TYPE ,T2.TRADER ,T2.COUNTER_ORG ,T1.COUNTER_TRADER ,T2.ASSET_TYPE ,T1.CREATE_TIME FROM WFL_ETR_ENTRUST T1 INNER JOIN WFL_ETR_ENTRUST_ADD T2 ON T2.ENTRUST_ID = T1.ENTRUST_ID and (T2.ASSET_TYPE1 != 'H01' or T2.ASSET_TYPE1 is null) LEFT JOIN ETR_FINISH_STATUS T4 ON T4.ENTRUST_ID = T1.ENTRUST_ID AND T1.ENTRUST_ID = T4.TRADE_ID LEFT JOIN PTL_PORTFOLIO T5 ON T5.PORTFOLIO_ID = T1.PORTFOLIO_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY T6 ON T6.PORTFOLIO_ID = T5.PORTFOLIO_ID
AND T6.USER_ID = #{userId}
LEFT JOIN FIN_PRODUCT T7 ON T7.FINPROD_ID = T1.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE fpt ON fpt.FINPROD_ID = T7.FINPROD_ID LEFT JOIN STL_SEC_ACCT_INFO SSAI ON T2.SEC_ACCT_ID = SSAI.SEC_ACCT_ID
left join (select distinct ACCT_NO acctNo1, BUSI_ACCT_NO busiAcctNo1, CCY ccy, ACCT_NAME acctName from STL_CAPACCT_INFO) c1 on T2.DEAL_CUR_ACCT = c1.acctNo1 and nvl(T1.CCY, 'CNY') = c1.ccy where T1.TRADE_MARKET in ('03','04') AND T2.ASSET_TYPE NOT IN ('F17')
AND T1.ENTRUST_DATE = to_date(#{sysDate},'yyyy-MM-dd')
AND T1.ENTRUST_ID = #{entrustId}
AND T1.ENTRUST_STATUS = #{entrustStatus}
AND T1.ENTRUST_DATE >=to_date(#{startDate},'yyyy-MM-dd')
AND T1.ENTRUST_DATE <=to_date(#{endDate},'yyyy-MM-dd')
) T1 where 1=1
#{portfolioId,jdbcType=VARCHAR}
AND T1.PS = #{ps,jdbcType=VARCHAR}
AND T1.FINPROD_MARKET_ID = #{secId,jdbcType=VARCHAR}
AND T1.FINPROD_TYPE2 = #{finprodType2,jdbcType=VARCHAR}
ORDER BY T1.CREATE_TIME DESC

SELECT TEMP.PORTFOLIO_ID AS portfolioId, PP.PORTFOLIO_NAME AS portfolioName, TEMP.SEC_ACCT_ID AS secAcctId, SSAI.SEC_ACCT_NAME AS secAcctName, TEMP.FINPROD_ID AS finprodId, FP.FINPROD_MARKET_ID AS finprodMarketId, CASE WHEN instr(FP.FINPROD_MARKET_ID,'.') > 0 THEN SUBSTR(FP.FINPROD_MARKET_ID,1,instr(FP.FINPROD_MARKET_ID,'.',-1,1)-1) ELSE FP.FINPROD_MARKET_ID END AS secId, FP.FINPROD_ABBR AS secName, TEMP.AMOUNT AS positionsNum, ESP.AMOUNT AS sellNum, CASE WHEN FP.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01} THEN MBVI.NETPRICE WHEN FP.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F06} THEN MFMI.CLOSE_PRICE WHEN FP.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F10} THEN MSP.CLOSE_PRICE ELSE NULL END AS price, CASE WHEN (NVL(T2.SHARE_AMT,0)+PSP.AMOUNT)=0 THEN NVL(PSV.DSC_COST_AMT,0)+NVL(T1.TRADE_AMT,0) ELSE ((NVL(PSV.DSC_COST_AMT,0)+NVL(T1.TRADE_AMT,0)) - (NVL(T2.SHARE_AMT,0)*(NVL(PSV.DSC_COST_AMT,0)+NVL(T1.TRADE_AMT,0))/(NVL(T2.SHARE_AMT,0)+PSP.AMOUNT))) END AS positionsAmt, PSP.AMOUNT AS ptlPositionsNum,
FP.FINPROD_TYPE2 AS finprodType2, FP.TRADE_MARKET AS tradeMarket, SSAI.TRD_ACCT_ID AS acctNo FROM ( SELECT PSP.CDATE AS CDATE, PSP.PORTFOLIO_ID AS PORTFOLIO_ID , PSP.SEC_ACCT_ID AS SEC_ACCT_ID , PSP.FINPROD_ID AS FINPROD_ID, PSP.BRANCH AS BRANCH, SUM(CASE WHEN PSP.HODING_TYPE IN (#{POSITION_TYPE_03}, #{POSITION_TYPE_05}) THEN NVL(PSP.AMOUNT,0) ELSE -1* NVL(PSP.AMOUNT,0) END) AS AMOUNT FROM PTL_SEC_POSITION PSP INNER JOIN PTL_PORTFOLIO PP ON PSP.PORTFOLIO_ID = PP.PORTFOLIO_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY PPA ON PP.PORTFOLIO_ID = PPA.PORTFOLIO_ID
AND PPA.USER_ID = #{userId}
WHERE PSP.BRANCH =0 AND PSP.HODING_TYPE IN (#{POSITION_TYPE_03}, #{POSITION_TYPE_04}, #{POSITION_TYPE_05}, #{POSITION_TYPE_06}) AND PSP.CDATE = #{sysDate} GROUP BY PSP.CDATE, PSP.PORTFOLIO_ID , PSP.SEC_ACCT_ID, PSP.FINPROD_ID, PSP.BRANCH )TEMP LEFT JOIN ( SELECT T.PORTFOLIO_ID, T.SEC_ACCT_ID, T.FINPROD_ID, T.BRANCH, T.CDATE, SUM(T.AMOUNT) AMOUNT FROM ETR_SEC_POSITION T GROUP BY T.PORTFOLIO_ID, T.SEC_ACCT_ID, T.FINPROD_ID, T.BRANCH, T.CDATE ) ESP ON TEMP.PORTFOLIO_ID = ESP.PORTFOLIO_ID AND TEMP.SEC_ACCT_ID = ESP.SEC_ACCT_ID AND TEMP.FINPROD_ID = ESP.FINPROD_ID AND TEMP.BRANCH = ESP.BRANCH AND TEMP.CDATE = ESP.CDATE LEFT JOIN FIN_PRODUCT FP ON TEMP.FINPROD_ID = FP.FINPROD_ID
LEFT JOIN MST_BOND_VALUATION_INFO MBVI ON FP.FINPROD_MARKET_ID = MBVI.SEC_ID AND MBVI.VALUE_DATE <= #{sysDate} AND MBVI.VALUE_SOURCE = #{VALUATION_SOURCE_CSD} LEFT JOIN (SELECT MAX(M.VALUE_DATE) VALUE_DATE, M.SEC_ID, M.VALUE_SOURCE FROM MST_BOND_VALUATION_INFO M WHERE M.VALUE_DATE <= #{sysDate} AND M.VALUE_SOURCE = #{VALUATION_SOURCE_CSD} GROUP BY M.SEC_ID,M.VALUE_SOURCE) MBVI2 ON MBVI.SEC_ID = MBVI2.SEC_ID AND MBVI.VALUE_SOURCE = MBVI2.VALUE_SOURCE AND MBVI.VALUE_DATE = MBVI2.VALUE_DATE
LEFT JOIN MST_FUND_MARKET_INFO MFMI ON FP.FINPROD_MARKET_ID = MFMI.FUND_CODE AND MFMI.VALUE_DATE <= #{sysDate} LEFT JOIN (SELECT MAX(MF.VALUE_DATE) VALUE_DATE, MF.FUND_CODE FROM MST_FUND_MARKET_INFO MF WHERE MF.VALUE_DATE <= #{sysDate} GROUP BY MF.FUND_CODE) MFMI2 ON MFMI.FUND_CODE = MFMI2.FUND_CODE AND MFMI.VALUE_DATE = MFMI2.VALUE_DATE
LEFT JOIN MST_SHARE_PRICE MSP ON FP.FINPROD_MARKET_ID = MSP.SHARES_ID AND MSP.DEAL_DATE <= #{sysDate} LEFT JOIN (SELECT MAX(MSP.DEAL_DATE) DEAL_DATE, MSP.SHARES_ID FROM MST_SHARE_PRICE MSP WHERE MSP.SHARES_ID = MSP.SHARES_ID AND MSP.DEAL_DATE <= #{sysDate} GROUP BY MSP.SHARES_ID) MSP2 ON MSP.SHARES_ID = MSP2.SHARES_ID AND MSP.DEAL_DATE = MSP2.DEAL_DATE LEFT JOIN ( SELECT T.PORTFOLIO_ID, T.SEC_ACCT_ID, T.FINPROD_ID, T.CDATE, SUM(T.DSC_COST_AMT) DSC_COST_AMT FROM PTL_SEC_VALUTION T WHERE T.CDATE = #{sysDate} - 1 GROUP BY T.PORTFOLIO_ID, T.SEC_ACCT_ID, T.FINPROD_ID, T.CDATE ) PSV ON TEMP.PORTFOLIO_ID = PSV.PORTFOLIO_ID AND TEMP.SEC_ACCT_ID = PSV.SEC_ACCT_ID AND TEMP.FINPROD_ID = PSV.FINPROD_ID AND PSV.CDATE = #{sysDate} - 1 LEFT JOIN ( SELECT TPD.FINPROD_ID, TPD.SEC_MANAGE_ACCT_ID, TPDA.PORTFOLIO_ID, SUM(NVL(TPD.TRADE_AMT,0)) AS TRADE_AMT, SUM(NVL(TPD.SHARE_AMT,0)) AS SHARE_AMT FROM TRD_PRODUCT_DEAL TPD LEFT JOIN TRD_PRODUCT_DEAL_ADD TPDA ON TPDA.TRADE_ID = TPD.TRADE_ID WHERE ( ( TPD.PS IN ( #{PS_T01}, #{PS_T46}, #{PS_T97}, #{PS_T04}) AND TPD.FINPROD_TYPE2 IN(#{FINPROD_TYPE_TG_F01}, #{FINPROD_TYPE_TG_F10}) ) OR ( TPD.PS IN ( #{PS_T01}, #{PS_T05}) AND TPD.FINPROD_TYPE2 IN(#{FINPROD_TYPE_TG_F06}) ) ) AND TPD.CHL_ID IS NULL AND TPD.TRADE_DATE = #{sysDate} GROUP BY TPD.FINPROD_ID, TPD.SEC_MANAGE_ACCT_ID, TPDA.PORTFOLIO_ID ) T1 ON TEMP.PORTFOLIO_ID = T1.PORTFOLIO_ID AND TEMP.SEC_ACCT_ID = T1.SEC_MANAGE_ACCT_ID AND TEMP.FINPROD_ID = T1.FINPROD_ID LEFT JOIN ( SELECT TPD.FINPROD_ID AS FINPROD_ID , TPD.SEC_MANAGE_ACCT_ID AS SEC_MANAGE_ACCT_ID, TPDA.PORTFOLIO_ID AS PORTFOLIO_ID, SUM(NVL(TPD.SHARE_AMT,0)) AS SHARE_AMT FROM TRD_PRODUCT_DEAL TPD LEFT JOIN TRD_PRODUCT_DEAL_ADD TPDA ON TPDA.TRADE_ID = TPD.TRADE_ID WHERE TPD.PS IN ( #{PS_T02}, #{PS_T03}, #{PS_T19} ) AND TPD.FINPROD_TYPE2 IN(#{FINPROD_TYPE_TG_F01}, #{FINPROD_TYPE_TG_F06}, #{FINPROD_TYPE_TG_F10}) AND TPD.CHL_ID IS NULL AND TPD.TRADE_DATE = #{sysDate} GROUP BY TPD.FINPROD_ID , TPD.SEC_MANAGE_ACCT_ID , TPDA.PORTFOLIO_ID ) T2 ON TEMP.PORTFOLIO_ID = T2.PORTFOLIO_ID AND TEMP.SEC_ACCT_ID = T2.SEC_MANAGE_ACCT_ID AND TEMP.FINPROD_ID= T2.FINPROD_ID LEFT JOIN ( SELECT T.PORTFOLIO_ID, T.SEC_ACCT_ID, T.FINPROD_ID, T.BRANCH, T.CDATE, SUM(T.AMOUNT) AMOUNT FROM PTL_SEC_POSITION T WHERE T.BRANCH=0 AND T.HODING_TYPE IN (#{POSITION_TYPE_03}) AND T.CDATE = #{sysDate} GROUP BY T.PORTFOLIO_ID, T.SEC_ACCT_ID, T.FINPROD_ID, T.BRANCH, T.CDATE ) PSP ON TEMP.PORTFOLIO_ID = PSP.PORTFOLIO_ID AND TEMP.SEC_ACCT_ID = PSP.SEC_ACCT_ID AND TEMP.FINPROD_ID = PSP.FINPROD_ID AND TEMP.BRANCH = PSP.BRANCH AND TEMP.CDATE = PSP.CDATE LEFT JOIN PTL_PORTFOLIO PP ON TEMP.PORTFOLIO_ID = PP.PORTFOLIO_ID LEFT JOIN STL_SEC_ACCT_INFO SSAI ON TEMP.SEC_ACCT_ID = SSAI.SEC_ACCT_ID WHERE FP.TRADE_MARKET IN (#{TRADE_PLACE_03}, #{TRADE_PLACE_04})
#{portfolioId,jdbcType=VARCHAR}
AND FP.TRADE_MARKET = #{tradeMarket,jdbcType=VARCHAR}
AND TEMP.SEC_ACCT_ID = #{secAcctId,jdbcType=VARCHAR}
AND FP.FINPROD_MARKET_ID = #{secId,jdbcType=VARCHAR}
AND FP.FINPROD_TYPE2 = #{finprodType2,jdbcType=VARCHAR}

SELECT A.VDATE startDate, A.MDATE endDate, ( SELECT MIN(C.VDATE) FROM FIN_CASH_PLAN C WHERE C.CASH_ID = B.CASH_ID ) firstPayDate, A.ISSUE_PRICE issuePrice, A.COUPON_SPECIES bondsType, E.BASIS basis, F.INT_TYPE intRateType, G.PAY_CYCLE yearIntRate, G.CALC_RULE calMethod, H.EXERCISE_DATE nextExeDate, H.EXERCISE_PRICE nextExercisePrice FROM FIN_PRODUCT A LEFT JOIN FIN_CASH_INFO B ON A.FINPROD_ID = B.FINPROD_ID AND B.FINPROD_TYPE = #{finprodType} AND B.CASH_TYPE_1 = #{cashType1} LEFT JOIN FIN_PRODUCT_TYPE D ON D.FINPROD_ID = A.FINPROD_ID
LEFT JOIN FIN_CASH_INFO T1 ON A.FINPROD_ID = T1.FINPROD_ID AND T1.CASH_TYPE_2 = 'C02' AND T1.FINPROD_TYPE = '01' left join (select FINPROD_ID, max(eff_date) as EFF_DATE from FIN_CASH_CALC_RULE group by FINPROD_ID) T2 on T2.FINPROD_ID = A.FINPROD_ID LEFT JOIN FIN_CASH_CALC_RULE E ON E.FINPROD_ID = A.FINPROD_ID and E.EFF_DATE = T2.EFF_DATE AND E.CASH_ID = T1.CASH_ID AND E.FINPROD_TYPE2 = 'F01' and E.IS_INITIAL = 'Y'
LEFT JOIN FIN_RATE_INFO F ON F.CASH_ID = B.CASH_ID AND F.FINPROD_TYPE2 = #{finprodType2} LEFT JOIN FIN_CASH_PAY_RULE G ON G.CASH_ID = B.CASH_ID AND G.FINPROD_TYPE2 = #{finprodType2} LEFT JOIN ( SELECT * FROM FIN_EXERCISE_PLAN WHERE EXERCISE_DATE IN ( SELECT MIN(EXERCISE_DATE) FROM FIN_EXERCISE_PLAN WHERE FINPROD_ID = #{finprodId} AND FINPROD_TYPE2 = #{finprodType2} AND EXERCISE_DATE >= #{sysDate} ) AND FINPROD_ID = #{finprodId} AND FINPROD_TYPE2 = #{finprodType2} AND EXERCISE_TYPE = #{EXEC_MODE02} AND EXERCISE_TYPE = #{EXEC_MODE01} and rownum = 1 ) H ON 1=1 WHERE A.FINPROD_ID = #{finprodId}

SELECT
       100 - NVL(sum(fcp.PRIN_AMT), 0)
FROM
     FIN_CASH_PLAN fcp
     inner join FIN_CASH_INFO fci
     on fcp.CASH_ID = fci.CASH_ID
WHERE
    fcp.FINPROD_ID = #{finprodId}

    AND fcp.MDATE < #{settleDate}
    and fci.CASH_TYPE_1 = #{cashType1}


where
    FINPROD_ID = #{finprodId}
    and FINPROD_TYPE2 = #{finprodType}
order by EFF_DATE

SELECT t.COUNTER_ORG code FROM ( SELECT DISTINCT etr_add.COUNTER_ORG FROM ETR_ENTRUST_ADD etr_add INNER JOIN ETR_ENTRUST etr ON etr.ENTRUST_ID = etr_add.ENTRUST_ID
etr.TRADE_MARKET = #{TRADE_PLACE_03}
AND etr.COUNTER_ID = #{counterId}
) t
t.COUNTER_ORG like concat('%',concat(#{param},'%'))

SELECT t.COUNTER_TRADER code FROM ( SELECT DISTINCT etr.COUNTER_TRADER FROM ETR_ENTRUST_ADD etr_add INNER JOIN ETR_ENTRUST etr ON etr.ENTRUST_ID = etr_add.ENTRUST_ID
etr.TRADE_MARKET = #{TRADE_PLACE_03}
AND etr_add.COUNTER_ORG = #{counterOrg}
) t
t.COUNTER_TRADER like concat('%',concat(#{param},'%'))

SELECT t.TRADER code FROM ( SELECT DISTINCT etr_add.TRADER FROM ETR_ENTRUST_ADD etr_add INNER JOIN ETR_ENTRUST etr ON etr.ENTRUST_ID = etr_add.ENTRUST_ID
etr.TRADE_MARKET = #{TRADE_PLACE_03}
) t
t.TRADER like concat('%',concat(#{param},'%'))

		select count(*) from FIN_CASH_INFO r
		inner join FIN_EXERCISE_PLAN q
		on r.cash_id = q.cash_id
		and q.exercise_type = #{EXEC_MODE_02}  
		where r.cash_type_2 = #{CASH_TYPE_2_C01}
		and r.branch = 0

			and r.finprod_id = #{finprodId}


            AND q.VDATE <=to_date(#{startDate},'yyyy-MM-dd')
            AND q.MDATE >=to_date(#{startDate},'yyyy-MM-dd')

		select t.scale from FIN_STDSEC_CONVERSE_RADIO t where t.branch = 0 and rownum = 1

			and t.finprod_id = #{finprodId}

		AND t.VDATE <= #{date}
        AND t.MDATE >= #{date}

select t.ACCT_NO from PTL_CAPACCT_INFO t left join STL_SEC_ACCT_INFO v on t.ACCT_NO = v.TRD_ACCT_ID
t.ACCT_TYPE = 'A07'
and t.PORTFOLIO_ID = #{portfolioId}
and v.TRADE_PLACE = #{tradeMarket}

select ssai.trade_place as tradeMarket, abs(nvl(SUM(t.amount),0)) as secNum from ETR_SEC_POSITION_FLOW t INNER JOIN STL_SEC_ACCT_INFO ssai on t.sec_acct_id = ssai.sec_acct_id and ssai.sec_acct_type = 'SEC' where t.finprod_id = 'XN_PRODID999' and t.hoding_type = 'E01' and t.branch = 0 and t.trade_id not in (SELECT ee.ENTRUST_ID FROM ETR_ENTRUST ee WHERE ee.PS IN ('T68', 'T69') UNION SELECT tsf.SEQNO FROM TRD_STASEC_FLOW tsf UNION SELECT tsf.SEQNO FROM TRD_TEMP_STASEC_FLOW tsf)
AND t.PORTFOLIO_ID = #{portfolioId}
AND ssai.trade_place = #{tradeMarket}
GROUP BY SSAI.TRADE_PLACE

select

from  etr_entrust WHERE ENTRUST_ID = #{entrustId}
union all
select

from wfl_etr_entrust WHERE ENTRUST_ID = #{entrustId}

select

from  etr_entrust_add WHERE ENTRUST_ID = #{entrustId}
union all
select

from wfl_etr_entrust_add WHERE ENTRUST_ID = #{entrustId}

		SELECT /** a.SEC_ID as secId,债券代码(市场代码)**/
/**c.FINPROD_ID AS finprodId, 资产代码(金融产品代码)**/
/**c.FINPROD_ABBR AS finprodAbbr,债券简称(金融产品简称)**/
/**a.VALUE_DATE AS valueDate,估值日**/
/**a.CLOSE_PRICE AS cloPrice,收盘价净价**/
/**a.AVERAGE_PRICE AS avgPrice,平均价净价**/
/**a.MAX_PRICE AS maxPrice,最高价净价**/
/** a.MIN_PRICE AS minPrice, 最低价净价**/
/** a.BUY_ONE_PRICE AS buyOnePrice,买一价净价**/
/**a.SELL_ONE_PRICE AS sellOnePrice,卖一价净价**/
       nvl(a.AVERAGE_PRICE, a.CLOSE_PRICE) as price
  FROM MST_BOND_MARKET_INFO a
 INNER JOIN FIN_PRODUCT c
    ON a.SEC_ID = c.FINPROD_MARKET_ID
 WHERE 1 = 1
   AND a.SEC_ID = #{secId}
   and a.VALUE_DATE = to_date(#{date},'yyyy-MM-dd') - 1

	SELECT /** a.SEC_ID as secId,债券代码(市场代码)**/
/**c.FINPROD_ID AS finprodId, 资产代码(金融产品代码)**/
/**c.FINPROD_ABBR AS finprodAbbr,债券简称(金融产品简称)**/
/**a.VALUE_DATE AS valueDate,估值日**/
/**a.CLOSE_PRICE AS cloPrice,收盘价净价**/
/**a.AVERAGE_PRICE AS avgPrice,平均价净价**/
/**a.MAX_PRICE AS maxPrice,最高价净价**/
/** a.MIN_PRICE AS minPrice, 最低价净价**/
/** a.BUY_ONE_PRICE AS buyOnePrice,买一价净价**/
/**a.SELL_ONE_PRICE AS sellOnePrice,卖一价净价**/
       nvl(a.AVERAGE_PRICE, a.CLOSE_PRICE) as price
  FROM INTERF_BOND_MARKET_INFO a
 INNER JOIN FIN_PRODUCT c
    ON a.SEC_ID = c.FINPROD_MARKET_ID
 WHERE 1 = 1
    AND a.SEC_ID = #{secId}
   and a.VALUE_DATE = to_date(#{date},'yyyy-MM-dd') - 1

select T2.TRADE_MARKET tradeMarket, T1.FINPROD_ID, T1.OTH_CODE, T1.OTH_TYPE, T1.OTH_NAME, T1.DECLARED_PRICE, T1.DECLARED_START_DATE, T1.DECLARED_END_DATE from FIN_PRODUCT_OTH_CODE T1 left join FIN_PRODUCT T2 on T1.finprod_id = T2.finprod_id
T1.branch = '0'
and T1.OTH_TYPE in
#{item}
and T1.FINPROD_ID = #{finprodId}

select
QUTO,
IPO_QUTO
from FIN_PRODUCT_QUTO

    1=1

        AND OTH_TYPE = #{othType,jdbcType=VARCHAR}


        and SEC_ACCT_ID = #{secAcctId,jdbcType=VARCHAR}


        and PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}


        and FINPROD_ID = #{finprodId,jdbcType=VARCHAR}


        and CDATE <= to_date(#{cDate}, 'yyyy-MM-dd')

    order by CDATE desc

select TEMP.PORTFOLIO_ID portfolioId, TEMP.SEC_ACCT_ID secAcctId, TEMP.FINPROD_ID finprodId, sum(TEMP.ENTRUST_NUM) entrustNum from( SELECT ETR_ENTRUST.PORTFOLIO_ID, ETR_ENTRUST_ADD.SEC_ACCT_ID, ETR_ENTRUST.FINPROD_ID, ETR_ENTRUST.VDATE, ETR_ENTRUST.MDATE, ETR_ENTRUST.ENTRUST_NUM FROM ETR_ENTRUST LEFT JOIN ETR_ENTRUST_ADD ON ETR_ENTRUST.ENTRUST_ID = ETR_ENTRUST_ADD.ENTRUST_ID
ETR_ENTRUST.ENTRUST_STATUS != #{entrustStatusClose,jdbcType=VARCHAR}
AND ETR_ENTRUST.ENTRUST_TYPE = #{entrustType,jdbcType=VARCHAR}
UNION ALL SELECT WFL_ETR_ENTRUST.PORTFOLIO_ID, WFL_ETR_ENTRUST_ADD.SEC_ACCT_ID, WFL_ETR_ENTRUST.FINPROD_ID, WFL_ETR_ENTRUST.VDATE, WFL_ETR_ENTRUST.MDATE, WFL_ETR_ENTRUST.ENTRUST_NUM FROM WFL_ETR_ENTRUST LEFT JOIN WFL_ETR_ENTRUST_ADD ON WFL_ETR_ENTRUST.ENTRUST_ID = WFL_ETR_ENTRUST_ADD.ENTRUST_ID
WFL_ETR_ENTRUST.ENTRUST_STATUS != #{entrustStatusClose,jdbcType=VARCHAR}
AND WFL_ETR_ENTRUST.ENTRUST_TYPE = #{entrustType,jdbcType=VARCHAR}
AND WFL_ETR_ENTRUST.ENTRUST_ID != #{entrustId,jdbcType=VARCHAR}
) TEMP left join FIN_PRODUCT_OTH_CODE on FIN_PRODUCT_OTH_CODE.FINPROD_ID = TEMP.FINPROD_ID and FIN_PRODUCT_OTH_CODE.BRANCH = '0' where TEMP.VDATE >= FIN_PRODUCT_OTH_CODE.DECLARED_START_DATE and TEMP.MDATE <= FIN_PRODUCT_OTH_CODE.DECLARED_END_DATE
and TEMP.SEC_ACCT_ID = #{secAcctId,jdbcType=VARCHAR}
and TEMP.PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}
and TEMP.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
GROUP BY TEMP.PORTFOLIO_ID,TEMP.SEC_ACCT_ID,TEMP.FINPROD_ID

select

from WFL_ETR_ENTRUST

    PS = #{ps_T04,jdbcType=VARCHAR}

        and PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}


        and  FINPROD_ID = #{finprodId,jdbcType=VARCHAR}


        and  ENTRUST_ID != #{entrustId,jdbcType=VARCHAR}

with acctid as (
    select ssai.SEC_ACCT_ID from STL_SEC_ACCT_INFO ssai
    where ssai.BOND_ID = (
        select ssai2.BOND_ID from STL_SEC_ACCT_INFO ssai2
        where ssai2.SEC_ACCT_ID = #{secAcctId,jdbcType=VARCHAR}
    )
)

select ee.entrust_id entrustId
from etr_entrust_add eea
left join etr_entrust ee
    on eea.entrust_id = ee.entrust_id
where
    eea.SEC_ACCT_ID in (select SEC_ACCT_ID from acctid)
    and ee.finprod_id = #{finprodId,jdbcType=VARCHAR}
    and ee.ps = #{ps,jdbcType=VARCHAR}
    and ee.FINPROD_TYPE2 = #{finprodType2,jdbcType=VARCHAR}
    and ee.trade_plat = #{tradePlat,jdbcType=VARCHAR}

UNION

select weea.entrust_id entrustId
from wfl_etr_entrust_add weea
left join wfl_etr_entrust wee
    on weea.entrust_id = wee.entrust_id
where
    weea.sec_acct_id in (select SEC_ACCT_ID from acctid)
    and wee.finprod_id = #{finprodId,jdbcType=VARCHAR}
    and weea.workflow_status = '01'
    and wee.ps = #{ps,jdbcType=VARCHAR}
    and wee.FINPROD_TYPE2 = #{finprodType2,jdbcType=VARCHAR}
    and wee.trade_plat = #{tradePlat,jdbcType=VARCHAR}

SELECT
    NETPRICE
FROM
    MST_BOND_VALUATION_INFO
WHERE
    SEC_ID = #{finprodMarketId}
    AND VALUE_SOURCE = #{VALUATION_SOURCE}
    AND VALUE_DATE = (
        SELECT MAX(VALUE_DATE) FROM MST_BOND_VALUATION_INFO
        WHERE VALUE_DATE < #{sysDate,jdbcType=DATE}
            AND SEC_ID = #{finprodMarketId}
            AND VALUE_SOURCE = #{VALUATION_SOURCE}
    )
